// Avoid pulling PUBLIC declarations with defaults into this translation unit,
// because Rcpp-exported definitions below carry defaults for autogenerated
// R wrappers. Yes, defaults are here in .cpp and in _public.hpp, so ensure
// they are synced!
#define RCPPTSKIT_IMPL
#include <RcppTskit.hpp>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <exception>
